import {esc,btn,title,badge,empty} from './ui.js';
import {courseCatalog,courseTopics,selectCourses} from './courses.js';

export function libraryTabs(active){return `<nav class="library-tabs" aria-label="Bagian video library"><a href="#videos" ${active==='courses'?'aria-current="page"':''}>Courses <span>${courseCatalog.length}</span></a><a href="#videos?view=videos" ${active==='videos'?'aria-current="page"':''}>Video pelajaran & pribadi</a></nav>`;}
function status(c){return badge(c.verification==='search-only'?'Provisional':'Sumber diperiksa',c.verification==='search-only'?'outline':'green');}
function libraryUrl(query,page){const q=new URLSearchParams();for(const key of ['search','language','topic','level','evidence'])if(query.get(key))q.set(key,query.get(key));const chosen=page??Number(query.get('page')||1);if(Number.isFinite(chosen)&&chosen>1)q.set('page',String(Math.floor(chosen)));return '#videos'+(q.size?'?'+q:'');}
function detailsUrl(c,q){return `#courses/${c.id}${q.size?'?return='+encodeURIComponent(q.toString()):''}`;}
function courseCard(c,state,q){const p=state.courseProgress?.[c.id];return `<article class="panel course-card"><div class="course-card-top"><span class="course-symbol" aria-hidden="true">${c.media.kind==='playlist'?'▤':'▶'}</span><span class="eyebrow">${c.media.kind==='playlist'?'Video series':'Full course video'}</span>${p?.watched?badge('Selesai · self-report','outline'):''}</div><div class="tag-row">${badge(c.language,'outline')}${badge(c.level,'outline')}${status(c)}</div><h2><a href="${esc(detailsUrl(c,q))}">${esc(c.title)}</a></h2><p class="course-publisher">${esc(c.publisher)}</p><p class="course-description">${esc(c.whyUseful)}</p><div class="tag-row course-topic-tags">${c.topics.slice(0,4).map(t=>badge(t,'outline')).join('')}</div><div class="course-card-footer">${btn(p?'Lanjut belajar':'Lihat course',detailsUrl(c,q),'secondary small')}<span>${c.format==='series'?'Seri terstruktur':'Course'}</span></div></article>`;}
export function courseLibrary(route,{state}){
 const q=route.query||new URLSearchParams(),result=selectCourses(q);
 const select=(name,label,options)=>`<label class="course-filter"><span>${label}</span><select name="${name}"><option value="">Semua</option>${options.map(([value,text])=>`<option value="${value}" ${q.get(name)===value?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
 return `${title('Watch · Understand · Apply','Video library','Pilih satu course, pahami idenya, lalu uji dengan praktik. Python, C++, DSA, design patterns, architecture, dan engineering principles.')}${libraryTabs('courses')}<div class="course-summary"><div><strong>${courseCatalog.length}</strong><span>course & series</span></div><div><strong>${courseCatalog.filter(c=>c.language==='English').length} / ${courseCatalog.filter(c=>c.language==='Indonesian').length}</strong><span>English / Indonesian</span></div><div><strong>${courseCatalog.filter(c=>c.verification==='primary-page-opened').length}</strong><span>sumber diperiksa</span></div><div><strong>${courseCatalog.filter(c=>c.verification==='search-only').length}</strong><span>provisional</span></div></div><form class="course-filters panel" data-search="videos"><label class="course-search"><span>Cari course</span><input name="search" type="search" maxlength="200" placeholder="Python, SOLID, architecture…" value="${esc(q.get('search')||'')}"></label>${select('language','Bahasa',[['English','English'],['Indonesian','Indonesian']])}${select('topic','Topik',Object.entries(courseTopics))}${select('level','Level',[['Beginner','Beginner'],['Intermediate','Intermediate'],['Advanced','Advanced']])}${select('evidence','Status riset',[['primary-page-opened','Sumber diperiksa'],['search-only','Provisional']])}<button type="submit" class="btn">Cari course</button><a class="course-reset" href="#videos">Reset filter</a></form><p class="course-results" role="status">${result.total} course ditemukan · Halaman ${result.page} dari ${result.pageCount}. Metadata sumber diperiksa 9 November 2026; bukan jaminan kualitas, kelengkapan, atau playback.</p><div class="grid grid-3 course-grid">${result.items.map(c=>courseCard(c,state,q)).join('')}</div>${!result.total?empty('Belum ada course cocok.','Ubah bahasa, topik atau kata pencarian. Cakupan DRY/KISS/YAGNI memiliki bacaan pendamping di bawah.',btn('Reset filter','#videos','secondary')):''}${result.pageCount>1?`<nav class="course-pagination" aria-label="Halaman course">${Array.from({length:result.pageCount},(_,i)=>`<a class="btn secondary small" href="${esc(libraryUrl(q,i+1))}" ${result.page===i+1?'aria-current="page"':''} aria-label="Halaman ${i+1}">${i+1}</a>`).join('')}</nav>`:''}<details class="panel principles-guide"><summary>Belajar prinsip: SOLID, DRY, KISS, YAGNI</summary><p>Mulai dari OOP dan tests. Gunakan SOLID untuk menilai tanggung jawab dan dependency; DRY untuk satu sumber pengetahuan; KISS untuk solusi yang mudah dipahami; YAGNI untuk menghindari fitur spekulatif. Terapkan pada satu perubahan nyata, lalu bandingkan trade-off.</p><p>Beberapa topik belum memiliki course video khusus yang cukup terverifikasi dalam riset ini. Bacaan primer pendamping:</p><div class="btn-row"><a class="btn secondary small" href="https://objectmentor.com/resources/articles/Principles_and_Patterns.pdf" target="_blank" rel="noopener noreferrer">SOLID & patterns ↗</a><a class="btn secondary small" href="https://media.pragprog.com/titles/tpp20/dry.pdf" target="_blank" rel="noopener noreferrer">DRY ↗</a><a class="btn secondary small" href="https://martinfowler.com/bliki/Yagni.html" target="_blank" rel="noopener noreferrer">YAGNI ↗</a></div></details><p class="footer-note">Course adalah alternatif belajar, bukan daftar wajib ditonton semuanya. Menonton tidak menambah mastery. Provisional berarti bukti sumber belum memadai; video dapat berubah atau tidak mendukung embed. Lab cloud/layanan pihak ketiga mungkin berbayar.</p>`;
}
export function courseView(route,{state}){
 const c=courseCatalog.find(c=>c.id===route.id),q=route.query||new URLSearchParams(),back=libraryUrl(new URLSearchParams(q.get('return')||''));
 if(!c)return empty('Course tidak ditemukan.','Pilih course dari library.',btn('Video library','#videos'));
 const p=state.courseProgress?.[c.id]||{notes:'',resumeSeconds:0,watched:false},playlist=c.media.kind==='playlist';
 return `${title(`${c.language} · ${c.level}`,c.title,c.publisher)}${libraryTabs('courses')}<div class="banner ${c.verification==='search-only'?'warning':''}">${status(c)} ${c.verification==='search-only'?'Course ini masih provisional. Sumber primer belum cukup terbaca; periksa kecocokan dan ketersediaan sebelum mengandalkannya.':'Halaman course/penerbit sudah diperiksa. Ini bukan review seluruh course atau sertifikasi playback.'}</div><div class="video-watch-layout course-watch-layout"><section><div id="course-player" class="video-player"><div class="video-placeholder"><span class="video-play-mark" aria-hidden="true">${playlist?'▤':'▶'}</span><h2>${playlist?'Belajar lewat playlist':'Siap belajar?'}</h2><p>${playlist?'Gunakan daftar episode dan kontrol asli YouTube.':'Pemutar dimuat saat kamu siap; tidak ada autoplay.'}</p><button type="button" class="btn" data-action="load-course" data-id="${c.id}">Muat ${playlist?'playlist':'course'}</button></div></div><div class="video-toolbar"><a class="btn secondary small" href="${esc(c.youtubeUrl)}" target="_blank" rel="noopener noreferrer">Buka ${playlist?'playlist':'course'} di YouTube ↗</a><button class="btn secondary small" type="button" data-action="unload-course" data-id="${c.id}">Tutup pemutar</button><a class="source-link" href="${esc(c.sourceUrl)}" target="_blank" rel="noopener noreferrer">Sumber riset ↗</a></div><p class="video-disclosure">Privacy-enhanced mode. Setelah dimuat, browser menghubungi YouTube. Iklan dan pembatasan penerbit tetap berlaku. Jika embed tidak tersedia, gunakan link YouTube; catatan tetap bisa disimpan.</p><section class="panel"><div class="eyebrow">Understand · Apply</div><h2>Terapkan setelah menonton</h2><p>${esc(c.whyUseful)}</p><div class="callout"><h3>Tugas praktik</h3><p>${esc(c.practice)}</p></div><h3>Prasyarat yang disarankan</h3><ul>${c.prerequisites.map(t=>`<li>${esc(t)}</li>`).join('')||'<li>Mulai dari dasar sesuai kebutuhanmu.</li>'}</ul><div class="tag-row">${c.topics.map(t=>badge(t,'outline')).join('')}</div><div class="btn-row">${btn('Practice lab','#practice','secondary small')}${btn('Learning path','#roadmap','secondary small')}</div></section><details class="panel section-gap"><summary>Batas riset & catatan sumber</summary><p>${esc(c.notes)}</p><p>Diperiksa ${esc(c.checkedAt)}. Level, prasyarat dan tugas praktik adalah saran kurasi. Bahasa kode course dapat berbeda dari runner Python/C++ aplikasi.</p><a href="${esc(c.courseUrl)}" target="_blank" rel="noopener noreferrer">Halaman course ↗</a></details></section><aside><form class="panel" data-form="course-progress" data-id="${c.id}"><div class="eyebrow">Catatan course</div><h2>Belajar dengan sengaja</h2><label class="field">Ringkasan, pertanyaan & episode terakhir<textarea name="notes" rows="8" maxlength="10000" placeholder="Apa yang berubah dalam pemahamanmu? Episode mana yang ingin dilanjutkan?">${esc(p.notes)}</textarea></label>${playlist?'<input type="hidden" name="resumeSeconds" value="0"><p class="muted">Untuk playlist, catat episode terakhir di catatan. Posisi episode pemutar tidak dilacak otomatis.</p>':`<label class="field">Bookmark manual (detik)<input type="number" name="resumeSeconds" min="0" max="172800" step="1" required value="${p.resumeSeconds}"></label><p class="muted">Hingga 48 jam untuk course panjang. Muat ulang pemutar untuk memakai bookmark baru.</p>`}<label class="choice"><input type="checkbox" name="watched" ${p.watched?'checked':''}><span>Selesai saya pelajari (self-report)</span></label><p class="muted">Tidak dihitung sebagai checkpoint, latihan, atau mastery. Disimpan di perangkat ini dan ikut backup.</p><button type="submit" class="btn">Simpan catatan course</button><div id="course-feedback" role="status" class="section-gap"></div></form><div class="section-gap">${btn('Kembali ke hasil pencarian',back,'secondary')}</div></aside></div>`;
}
